#!/usr/bin/env python3
"""NakshaTech ERP HRMS backend patch for the EXACT files supplied 2026-10-29.
Usage:
  python NAKSHA_HRMS_BACKEND_PATCH.py --check
  # Back up DB before the migration. Run migration in backend container:
  python /tmp/NAKSHA_HRMS_BACKEND_PATCH.py --migrate
  # From project root on Windows:
  python NAKSHA_HRMS_BACKEND_PATCH.py --apply-source
Does not reset user data, touch authentication or overwrite other modules.
"""
import argparse
import base64
import hashlib
import os
from pathlib import Path
from datetime import datetime
import shutil
import sys

FILES = {
    'router.py': ('16858606eed61de867d847d4c297ce29d2663c4f51b47091d88b8da5798e9f8e', ''),
    'models.py': ('bded09b5834c7cdc14a24f0187b6ab867045713fff079c9e762c1072ec32020e', ''),
    'policy.py': ('26d808d0b0acc052568df3470e5cd488f91ae62ff36b19f2001a8f38a8b71c33', ''),
}
TARGET = Path("backend/app/modules/hrms")
COLUMNS = [
    ("duration", "VARCHAR(20) NOT NULL DEFAULT 'full_day'"),
    ("half_day_session", "VARCHAR(20)"),
    ("office_time", "VARCHAR(5)"),
    ("cancellation_status", "VARCHAR(20)"),
    ("cancellation_reason", "TEXT"),
    ("cancellation_requested_at", "TIMESTAMP"),
    ("cancellation_decided_at", "TIMESTAMP"),
    ("cancellation_reviewer_id", "INTEGER REFERENCES users(id)"),
    ("cancellation_note", "TEXT"),
]

def migration():
    from sqlalchemy import create_engine, inspect, text
    from app.core.config import settings
    from app.core.database import engine
    if settings.app_env.lower() != "development" or settings.is_production:
        raise SystemExit("REFUSED: migration is only enabled for local development")
    if engine.url.get_backend_name() != "postgresql" or engine.url.host not in ("db", "localhost", "127.0.0.1"):
        raise SystemExit("REFUSED: unexpected database target")
    inspector = inspect(engine)
    if "hrms_leave_requests" not in inspector.get_table_names():
        raise SystemExit("REFUSED: hrms_leave_requests does not exist")
    existing = {c["name"] for c in inspector.get_columns("hrms_leave_requests")}
    todo = [(n,typ) for n,typ in COLUMNS if n not in existing]
    print("Existing HRMS rows untouched; columns to add:", [n for n,_ in todo])
    if not todo:
        print("MIGRATION ALREADY APPLIED")
        return
    with engine.begin() as connection:
        connection.execute(text("SELECT pg_advisory_xact_lock(17592026)"))
        for name, coldef in todo:
            connection.execute(text(f"ALTER TABLE hrms_leave_requests ADD COLUMN IF NOT EXISTS {name} {coldef}"))
    print("MIGRATION APPLIED. No existing leave status or amount changed.")

def source(root, action):
    paths = {name: root / TARGET / name for name in FILES}
    unknown = []
    for name,path in paths.items():
        if not path.is_file():
            unknown.append(f"MISSING {path}")
            continue
        sha, value = FILES[name]
        current_hash = hashlib.sha256(path.read_bytes()).hexdigest()
        patched_hash = hashlib.sha256(base64.b64decode(value)).hexdigest()
        if current_hash == sha:
            print("READY", path)
        elif current_hash == patched_hash:
            print("ALREADY PATCHED", path)
        else:
            unknown.append(f"MODIFIED/UNKNOWN {path}: SHA256 {current_hash}")
    if unknown:
        raise SystemExit("REFUSED to change any file:\n" + "\n".join(unknown))
    if action == "check":
        return
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    base = Path(os.environ.get("LOCALAPPDATA") or str(Path.home())) / "NakshaTech" / "HRMS_patch_backups" / timestamp
    base.mkdir(parents=True, exist_ok=False)
    for name,path in paths.items():
        sha, value = FILES[name]
        if hashlib.sha256(path.read_bytes()).hexdigest() != sha:
            continue
        shutil.copy2(path, base / name)
        temp = path.with_name(path.name + ".patch-tmp")
        temp.write_bytes(base64.b64decode(value))
        temp.replace(path)
        print("PATCHED", path)
    print("Source backups:", base)
    print("IMPORTANT: Run database migration BEFORE restarting/rebuilding the backend")

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    actions = parser.add_mutually_exclusive_group(required=True)
    actions.add_argument("--check", action="store_true")
    actions.add_argument("--apply-source", action="store_true")
    actions.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    if args.migrate:
        migration()
    else:
        source(Path.cwd(), "apply" if args.apply_source else "check")

if __name__ == "__main__":
    main()
